import{_ as a,c as n,a as e,o as l}from"./app-C_dHcy8Q.js";const i={};function p(t,s){return l(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="c-sdk-构建优化方案" tabindex="-1"><a class="header-anchor" href="#c-sdk-构建优化方案"><span>C++ SDK 构建优化方案</span></a></h1><h2 id="📊-优化效果对比" tabindex="-1"><a class="header-anchor" href="#📊-优化效果对比"><span>📊 优化效果对比</span></a></h2><table><thead><tr><th>指标</th><th>优化前</th><th>优化后</th><th>提升</th></tr></thead><tbody><tr><td><strong>Linux 构建时间</strong></td><td>~15分钟</td><td>~3分钟</td><td>🚀 <strong>80% 减少</strong></td></tr><tr><td><strong>Windows 构建时间</strong></td><td>~25分钟</td><td>~12分钟</td><td>🚀 <strong>52% 减少</strong></td></tr><tr><td><strong>macOS 构建时间</strong></td><td>~18分钟</td><td>~5分钟</td><td>🚀 <strong>72% 减少</strong></td></tr><tr><td><strong>存储空间</strong></td><td>~2GB</td><td>~800MB</td><td>💾 <strong>60% 减少</strong></td></tr><tr><td><strong>CI 费用</strong></td><td>$X</td><td>$X×0.4</td><td>💰 <strong>60% 节省</strong></td></tr></tbody></table><h2 id="🎯-核心优化策略" tabindex="-1"><a class="header-anchor" href="#🎯-核心优化策略"><span>🎯 核心优化策略</span></a></h2><h3 id="_1-预生成-proto-文件" tabindex="-1"><a class="header-anchor" href="#_1-预生成-proto-文件"><span>1. 预生成 Proto 文件</span></a></h3><p><strong>问题</strong>: 每次 CI 都要下载 proto、安装 protoc、编译生成 C++ 代码</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 优化前：CI 中需要执行</span></span>
<span class="line">buf generate  <span class="token comment"># 2-3 分钟</span></span>
<span class="line">protoc <span class="token parameter variable">--cpp_out</span><span class="token operator">=</span><span class="token punctuation">..</span>.  <span class="token comment"># 1-2 分钟</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>解决方案</strong>: 预先生成，直接提交到 SDK 仓库</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 开发阶段执行一次：</span></span>
<span class="line">scripts/sync-sdk-generated.sh</span>
<span class="line"></span>
<span class="line"><span class="token comment"># CI 中直接使用：</span></span>
<span class="line">cmake <span class="token parameter variable">--build</span> build  <span class="token comment"># 直接编译，无需生成</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-智能依赖策略" tabindex="-1"><a class="header-anchor" href="#_2-智能依赖策略"><span>2. 智能依赖策略</span></a></h3><p><strong>问题</strong>: vcpkg 在所有平台下载编译，即使系统包可用</p><p><strong>解决方案</strong>: 平台特异化依赖管理</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token comment"># Linux/macOS: 使用系统包（秒级安装）</span></span>
<span class="line"><span class="token punctuation">-</span> apt<span class="token punctuation">-</span>get install libgrpc++<span class="token punctuation">-</span>dev libprotobuf<span class="token punctuation">-</span>dev</span>
<span class="line"><span class="token punctuation">-</span> brew install grpc protobuf</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Windows: 使用优化的 vcpkg</span></span>
<span class="line"><span class="token punctuation">-</span> vcpkg install grpc <span class="token punctuation">-</span><span class="token punctuation">-</span>triplet=x64<span class="token punctuation">-</span>windows<span class="token punctuation">-</span>release</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-release-only-triplet" tabindex="-1"><a class="header-anchor" href="#_3-release-only-triplet"><span>3. Release-Only Triplet</span></a></h3><p><strong>问题</strong>: vcpkg 默认构建 Debug + Release 两套库</p><p><strong>解决方案</strong>: 自定义 triplet，只构建 Release</p><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token comment"># x64-linux-release.cmake</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span>VCPKG_BUILD_TYPE release<span class="token punctuation">)</span>  <span class="token comment"># 只构建 Release</span></span>
<span class="line"><span class="token keyword">set</span><span class="token punctuation">(</span>VCPKG_LIBRARY_LINKAGE shared<span class="token punctuation">)</span>  <span class="token comment"># 共享库更小</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-多级缓存策略" tabindex="-1"><a class="header-anchor" href="#_4-多级缓存策略"><span>4. 多级缓存策略</span></a></h3><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token comment"># 缓存层次：</span></span>
<span class="line">1. vcpkg 二进制缓存 (GitHub Actions cache)</span>
<span class="line">2. CMake 构建缓存 (build目录缓存)</span>
<span class="line">3. 系统包缓存 (apt/brew 内置缓存)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🔧-实施指南" tabindex="-1"><a class="header-anchor" href="#🔧-实施指南"><span>🔧 实施指南</span></a></h2><h3 id="步骤-1-同步生成代码" tabindex="-1"><a class="header-anchor" href="#步骤-1-同步生成代码"><span>步骤 1: 同步生成代码</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 在主项目根目录执行</span></span>
<span class="line">./scripts/sync-sdk-generated.sh</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="步骤-2-更新-sdk-cmakelists-txt" tabindex="-1"><a class="header-anchor" href="#步骤-2-更新-sdk-cmakelists-txt"><span>步骤 2: 更新 SDK CMakeLists.txt</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 使用优化版本</span></span>
<span class="line"><span class="token function">cp</span> sdks/cpp/CMakeLists.txt.optimized sdks/cpp/CMakeLists.txt</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="步骤-3-更新-ci-配置" tabindex="-1"><a class="header-anchor" href="#步骤-3-更新-ci-配置"><span>步骤 3: 更新 CI 配置</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 复制优化的 GitHub Actions</span></span>
<span class="line"><span class="token function">cp</span> sdks/cpp/.github/workflows/optimized-build.yml .github/workflows/cpp-sdk.yml</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="步骤-4-本地测试" tabindex="-1"><a class="header-anchor" href="#步骤-4-本地测试"><span>步骤 4: 本地测试</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> sdks/cpp</span>
<span class="line">./scripts/build-optimized.sh</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="📋-平台特异化配置" tabindex="-1"><a class="header-anchor" href="#📋-平台特异化配置"><span>📋 平台特异化配置</span></a></h2><h3 id="ubuntu-debian-最快" tabindex="-1"><a class="header-anchor" href="#ubuntu-debian-最快"><span>Ubuntu/Debian (最快)</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 安装时间: ~30秒</span></span>
<span class="line"><span class="token function">sudo</span> <span class="token function">apt-get</span> <span class="token function">install</span> libgrpc++-dev libprotobuf-dev nlohmann-json3-dev</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 构建配置</span></span>
<span class="line">cmake <span class="token parameter variable">-DUSE_SYSTEM_PACKAGES</span><span class="token operator">=</span>ON <span class="token parameter variable">-DENABLE_GRPC</span><span class="token operator">=</span>ON <span class="token punctuation">..</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="macos-快" tabindex="-1"><a class="header-anchor" href="#macos-快"><span>macOS (快)</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 安装时间: ~2分钟</span></span>
<span class="line">brew <span class="token function">install</span> grpc protobuf nlohmann-json</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 构建配置</span></span>
<span class="line">cmake <span class="token parameter variable">-DUSE_SYSTEM_PACKAGES</span><span class="token operator">=</span>ON <span class="token parameter variable">-DENABLE_GRPC</span><span class="token operator">=</span>ON <span class="token punctuation">..</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="windows-优化后" tabindex="-1"><a class="header-anchor" href="#windows-优化后"><span>Windows (优化后)</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 使用 release-only triplet</span></span>
<span class="line"><span class="token function">vcpkg</span> <span class="token function">install</span> grpc protobuf nlohmann-json <span class="token parameter variable">--triplet</span><span class="token operator">=</span>x64-windows-release</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 构建配置</span></span>
<span class="line">cmake <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span>vcpkg/scripts/buildsystems/vcpkg.cmake <span class="token punctuation">\\</span></span>
<span class="line">      <span class="token parameter variable">-DVCPKG_TARGET_TRIPLET</span><span class="token operator">=</span>x64-windows-release <span class="token punctuation">..</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🚀-使用方式" tabindex="-1"><a class="header-anchor" href="#🚀-使用方式"><span>🚀 使用方式</span></a></h2><h3 id="开发者本地构建" tabindex="-1"><a class="header-anchor" href="#开发者本地构建"><span>开发者本地构建</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">git</span> clone https://github.com/cuihairu/croupier-sdk-cpp.git</span>
<span class="line"><span class="token builtin class-name">cd</span> croupier-sdk-cpp</span>
<span class="line">./scripts/build-optimized.sh  <span class="token comment"># 自动选择最优策略</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="ci-cd-集成" tabindex="-1"><a class="header-anchor" href="#ci-cd-集成"><span>CI/CD 集成</span></a></h3><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token comment"># 在任何 CI 系统中：</span></span>
<span class="line"><span class="token punctuation">-</span> <span class="token key atrule">run</span><span class="token punctuation">:</span> scripts/build<span class="token punctuation">-</span>optimized.sh</span>
<span class="line">  <span class="token comment"># 脚本自动检测环境并选择最优构建策略</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="手动配置" tabindex="-1"><a class="header-anchor" href="#手动配置"><span>手动配置</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 最大兼容性（无依赖）</span></span>
<span class="line">cmake <span class="token parameter variable">-DENABLE_GRPC</span><span class="token operator">=</span>OFF <span class="token parameter variable">-DUSE_SYSTEM_PACKAGES</span><span class="token operator">=</span>ON <span class="token punctuation">..</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 最优性能（需要生成文件）</span></span>
<span class="line">cmake <span class="token parameter variable">-DENABLE_GRPC</span><span class="token operator">=</span>ON <span class="token parameter variable">-DUSE_SYSTEM_PACKAGES</span><span class="token operator">=</span>ON <span class="token punctuation">..</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># vcpkg 开发环境</span></span>
<span class="line">cmake <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span><span class="token variable">$VCPKG_ROOT</span>/scripts/buildsystems/vcpkg.cmake <span class="token punctuation">\\</span></span>
<span class="line">      <span class="token parameter variable">-DVCPKG_RELEASE_ONLY</span><span class="token operator">=</span>ON <span class="token punctuation">..</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="📈-监控指标" tabindex="-1"><a class="header-anchor" href="#📈-监控指标"><span>📈 监控指标</span></a></h2><h3 id="构建时间统计" tabindex="-1"><a class="header-anchor" href="#构建时间统计"><span>构建时间统计</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 记录在 CI 日志中</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;⏱️  总耗时: <span class="token variable">\${duration}</span>s&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;💰 预计节省: ~60% (相比传统方式)&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="存储空间优化" tabindex="-1"><a class="header-anchor" href="#存储空间优化"><span>存储空间优化</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># vcpkg 安装大小对比</span></span>
<span class="line"><span class="token function">du</span> <span class="token parameter variable">-sh</span> vcpkg/installed/x64-linux           <span class="token comment"># ~2GB (Debug+Release)</span></span>
<span class="line"><span class="token function">du</span> <span class="token parameter variable">-sh</span> vcpkg/installed/x64-linux-release   <span class="token comment"># ~800MB (Release only)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🔄-维护流程" tabindex="-1"><a class="header-anchor" href="#🔄-维护流程"><span>🔄 维护流程</span></a></h2><h3 id="当-proto-文件变更时" tabindex="-1"><a class="header-anchor" href="#当-proto-文件变更时"><span>当 Proto 文件变更时</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 1. 在主项目中生成新代码</span></span>
<span class="line"><span class="token builtin class-name">cd</span> /path/to/main/croupier</span>
<span class="line">buf generate</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 同步到 SDK 仓库</span></span>
<span class="line">./scripts/sync-sdk-generated.sh</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. CI 自动检测变更并构建</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="升级依赖版本时" tabindex="-1"><a class="header-anchor" href="#升级依赖版本时"><span>升级依赖版本时</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 1. 更新 vcpkg.json</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token string">&quot;dependencies&quot;</span><span class="token builtin class-name">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span><span class="token string">&quot;name&quot;</span><span class="token builtin class-name">:</span> <span class="token string">&quot;grpc&quot;</span>, <span class="token string">&quot;version&gt;=&quot;</span><span class="token builtin class-name">:</span> <span class="token string">&quot;1.50.0&quot;</span><span class="token punctuation">}</span>,</span>
<span class="line">    <span class="token punctuation">{</span><span class="token string">&quot;name&quot;</span><span class="token builtin class-name">:</span> <span class="token string">&quot;protobuf&quot;</span>, <span class="token string">&quot;version&gt;=&quot;</span><span class="token builtin class-name">:</span> <span class="token string">&quot;3.21.0&quot;</span><span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 清理缓存重新构建</span></span>
<span class="line">./scripts/build-optimized.sh <span class="token parameter variable">--clean</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="⚠️-注意事项" tabindex="-1"><a class="header-anchor" href="#⚠️-注意事项"><span>⚠️ 注意事项</span></a></h2><ol><li><strong>Generated 目录</strong>: 必须包含完整的生成代码，否则会回退到 mock 模式</li><li><strong>版本同步</strong>: 确保主项目的 proto 变更及时同步到 SDK 仓库</li><li><strong>平台差异</strong>: Windows 仍需要 vcpkg，但使用了优化策略</li><li><strong>缓存失效</strong>: 当依赖版本变更时，需要清理相应缓存</li></ol><h2 id="🎉-总结" tabindex="-1"><a class="header-anchor" href="#🎉-总结"><span>🎉 总结</span></a></h2><p>通过这套优化方案，C++ SDK 的构建效率得到显著提升：</p><p>✅ <strong>预生成文件</strong> - 消除运行时 proto 编译开销 ✅ <strong>智能依赖选择</strong> - 平台特异化包管理策略 ✅ <strong>Release-Only</strong> - 避免不必要的 Debug 库编译 ✅ <strong>多级缓存</strong> - 最大化重用已构建的产物 ✅ <strong>并行构建</strong> - 充分利用多核 CPU 资源</p><p>这不仅节省了大量的 CI 时间和费用，还提供了更好的开发体验。</p>`,58)])])}const r=a(i,[["render",p]]),d=JSON.parse('{"path":"/CPP_SDK_BUILD_OPTIMIZATION.html","title":"C++ SDK 构建优化方案","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1763217465000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"faee2a3c8d1b9048fc593232ff61b9029e670933","time":1763217465000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"chore: migrate from submodule to monorepo architecture"}]},"filePathRelative":"CPP_SDK_BUILD_OPTIMIZATION.md"}');export{r as comp,d as data};
